from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.models import Payment
from ledgerly.support import process_refund_request
from ledgerly.errors import BillingError
from ledgerly import audit
T0=datetime(2026,1,1,tzinfo=timezone.utc)
p=Payment('p','i',Decimal('100.00'),status='captured',created_at=T0,captured_at=T0)
process_refund_request(p,'10.00','u',T0,idempotency_key='k')
process_refund_request(p,'10.00','u',T0,idempotency_key='k')
print('idem', p.refunded_amount)
p2=Payment('p2','i',Decimal('1000.00'),status='captured',created_at=T0,captured_at=T0)
try: process_refund_request(p2,'600.00','u',T0)
except BillingError as e: print('approval', e.code)
process_refund_request(p2,'600.00','u',T0,approved_by='boss')
print(p2.refunded_amount)
p3=Payment('p3','i',Decimal('10.00'),status='authorized')
try: process_refund_request(p3,'1.00','u',T0)
except BillingError as e: print('state', e.code)
try: process_refund_request(p,'100.00','u',T0)
except BillingError as e: print('over', e.code)
try: process_refund_request(p,'0','u',T0)
except BillingError as e: print('zero', e.code)
print(audit.events('payment_refunded'))
""}

